# ==============================================================================# 065_CODE_QUALITY_AUDITOR.py# IOTEC MISSION CONTROL# ==============================================================================from pathlib import Pathimport astimport sqlite3import tokenizeimport hashlibDB = "mission_control.db"class CodeQualityAuditor:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.execute("""        CREATE TABLE IF NOT EXISTS code_quality(            id INTEGER PRIMARY KEY AUTOINCREMENT,            module TEXT,            status TEXT,            problem TEXT,            size INTEGER,            sha256 TEXT        )        """)        self.conn.commit()    # -----------------------------------------------------------------    def clear(self):        self.conn.execute("DELETE FROM code_quality")        self.conn.commit()    # -----------------------------------------------------------------    def sha(self, file):        h = hashlib.sha256()        with open(file, "rb") as f:            while True:                b = f.read(65536)                if not b:                    break                h.update(b)        return h.hexdigest()    # -----------------------------------------------------------------    def register(self, module, status, problem, size, sha):        self.conn.execute("""        INSERT INTO code_quality(            module,            status,            problem,            size,            sha256        )        VALUES(?,?,?,?,?)        """, (            module,            status,            problem,            size,            sha        ))    # -----------------------------------------------------------------    def inspect(self, file):        path = Path(file)        size = path.stat().st_size        sha = self.sha(path)        raw = path.read_bytes()        if raw.startswith(b'\xef\xbb\xbf'):            return "WARNING", "UTF8_BOM", size, sha        try:            text = raw.decode("utf-8")        except UnicodeDecodeError:            return "ERROR", "ENCODING", size, sha        if not text.strip():            return "WARNING", "EMPTY_FILE", size, sha        if "\t" in text:            return "WARNING", "TAB_CHARACTER", size, sha        try:            tokenize.generate_tokens(iter(text.splitlines(True)).__next__)        except Exception as e:            return "ERROR", f"TOKENIZE: {e}", size, sha        try:            ast.parse(text)        except SyntaxError as e:            return (                "ERROR",                f"SYNTAX L{e.lineno}: {e.msg}",                size,                sha            )        except Exception as e:            return (                "ERROR",                str(e),                size,                sha            )        return "OK", "VALID", size, sha    # -----------------------------------------------------------------    def run(self, folder="."):        self.clear()        total = 0        ok = 0        errors = 0        warnings = 0        for py in Path(folder).rglob("*.py"):            total += 1            status, problem, size, sha = self.inspect(py)            self.register(                py.name,                status,                problem,                size,                sha            )            if status == "OK":                ok += 1            elif status == "WARNING":                warnings += 1            else:                errors += 1        self.conn.commit()        return total, ok, warnings, errors    # -----------------------------------------------------------------    def top_errors(self):        cur = self.conn.execute("""        SELECT            problem,            COUNT(*) total        FROM code_quality        WHERE status='ERROR'        GROUP BY problem        ORDER BY total DESC        LIMIT 20        """)        return cur.fetchall()# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    audit = CodeQualityAuditor()    total, ok, warn, err = audit.run()    print("=" * 70)    print("CODE QUALITY AUDITOR")    print("=" * 70)    print("Arquivos :", total)    print("OK       :", ok)    print("Warnings :", warn)    print("Erros    :", err)    print("=" * 70)    print("TOP ERROS")    print("=" * 70)    for item in audit.top_errors():        print(            str(item[0]).ljust(45),            item[1]        )